      var _fgZone = window._aioFgZoneIndex;
      var _fgZoneLabel = function(z){ return ['극단 공포','공포','중립','탐욕','극단 탐욕'][z] || '?'; };
      var A = window.AIO || {}, ds = window.DATA_SNAPSHOT || {}, ld = window._liveData || {};
      var reg = (typeof window._aioRegimeNow === 'function') ? window._aioRegimeNow() : {};
      var vix = _num(reg.vix), fg = _num(reg.fg), spx = _num(reg.spx);
      var vb = _vixBand(vix), fz = _fgZone(fg);
      // v50.45 [자율 루프] 뉴스 신호 흡수 — risk/dominantTopic/action을 뉴스 인지로.
      var newsSignal = (typeof window._aioComputeNewsSignal === 'function') ? window._aioComputeNewsSignal() : null;
      // News may remain visible as reference material, but it can affect
      // risk/action only when its own publication/source gate is satisfied.
      var minNewsSample = Number(window.AIO_ARCH && window.AIO_ARCH.MIN_NEWS_ANALYSIS_SAMPLE);
      var newsDecisionSignal = Number.isInteger(minNewsSample) && minNewsSample > 0
        && newsSignal && newsSignal.available === true && newsSignal.allowedUse === true
