        var retainedLabel = retainedKst ? (retainedKst.slice(0, 10) === todayKst ? '' : (+retainedKst.slice(5, 7)) + '/' + (+retainedKst.slice(8, 10)) + ' ') + retainedKst.slice(11, 16) + ' 기준 직전 검증본' : '';
