function _aioRenderPageActionHub(pageId) {
  // v51.57: 과도한 설명 카드 제거 — action hub 미렌더
  var page = document.getElementById('page-' + pageId);
  if (!page) return null;
  var old = page.querySelector('.aio-action-hub[data-aio-hub-page="' + pageId + '"]');
  if (old) old.remove();
  return null;
}

function _aioFoldDensePageControls(pageId) {
  var page = document.getElementById('page-' + pageId);
  if (!page || page.querySelector('.aio-page-advanced-toggle[data-fold-page="' + pageId + '"]')) return;
  // ID 기반 직접 지정 — 텍스트/인라인 스타일 의존 제거
  var selectors = [];
  if (pageId === 'market-news') selectors = ['#news-source-guide', '#news-progress-wrap'];
  // P1449: the screener backtest panel is the primary native IC view inside its own named tab
  // (P1443). Folding it into a closed <details> was the pre-P1443 legacy text-log policy — the
  // legacy text log no longer exists, so the screener folds nothing. New primary panels may
  // also declare data-aio-fold="never"; this fold skips such nodes defensively.
  if (pageId === 'screener') selectors = [];
  // P1449: restore a screen state where a previous-fold contract already tucked the panel into
  // a closed <details> — the panel goes back to its document position and the stale toggle goes.
  var legacyFold = page.querySelector('.aio-page-advanced-toggle[data-fold-page="screener"]');
  if (legacyFold) {
    var foldedPanel = page.querySelector('#screener-backtest-panel');
    if (foldedPanel && legacyFold.parentNode) {
      foldedPanel.classList.remove('aio-page-dense-folded');
      legacyFold.parentNode.insertBefore(foldedPanel, legacyFold);
    }
    legacyFold.remove();
  }
  // v51.40/P532: signal lockout is a hidden legacy sink, not a collapsible default-route section.
  if (pageId === 'signal') selectors = [];
  if (pageId === 'fxbond') selectors = ['.insight-box.box-collapsed'];
  if (pageId === 'guide') selectors = ['.insight-box.box-collapsed'];
  var nodes = [];
  selectors.forEach(function(sel) {
    try {
      page.querySelectorAll(sel).forEach(function(node) {
        if (node && nodes.indexOf(node) < 0 && !node.closest('.aio-page-advanced-toggle') && node.dataset.aioFold !== 'never') nodes.push(node);
      });
    } catch(_) {}
  });
  // page 내부에 존재하는 노드만 유지 (직접 자식 또는 하위)
  nodes = nodes.filter(function(n) { return n && n.closest && n.closest('#page-' + pageId); });
  if (!nodes.length) return;
  var details = document.createElement('details');
  details.className = 'aio-page-advanced-toggle';
  details.setAttribute('data-fold-page', pageId);
  var label = pageId === 'market-news' ? '소스 안내·상태'
    : pageId === 'screener' ? '팩터 검증 텍스트 로그'
    : '참고/상세 내용';
  details.innerHTML = '<summary>' + label + '</summary><div class="aio-page-advanced-body"></div>';
  var body = details.querySelector('.aio-page-advanced-body');
  // 접힌 섹션의 anchor: 첫 번째 노드의 다음 형제 앞에 삽입
  var firstNode = nodes[0];
  if (firstNode && firstNode.parentNode) {
    firstNode.parentNode.insertBefore(details, firstNode);
  } else {
    var anchor = page.querySelector('.aio-action-hub') || page.querySelector('.aio-decision-header') || page.firstElementChild;
    if (anchor && anchor.parentNode) anchor.parentNode.insertBefore(details, anchor.nextSibling);
  }
  nodes.forEach(function(node) {
    node.classList.add('aio-page-dense-folded');
    body.appendChild(node);
  });
}

window._aioApplyPageBodyRedesign = function(pageId) {
  pageId = String(pageId || '').replace(/^page-/, '');
  if (!pageId) return;
  try { _aioRenderPageActionHub(pageId); } catch(_) {}
  try { _aioFoldDensePageControls(pageId); } catch(_) {}
};


