window.AIO.computeTAMEstimate = async function(ticker) {
  if (!ticker) return null;
  ticker = ticker.toUpperCase().trim();
  window._tamCache = window._tamCache || {};
  var cached = window._tamCache[ticker];
  if (cached && (Date.now() - cached.ts < 30 * 60 * 1000)) return cached.data;
  var indicators = [];
  var tamEstimate = null, cagrEstimate = null, sicCode = null, industryName = null;
  // 소스 1: SEC SIC code + AIO_INDUSTRY_TAM_REGISTRY
  try {
    var biz = await window.AIO.fetchSECBusinessDescription(ticker);
    if (biz && biz.available && biz.sic) {
      sicCode = String(biz.sic);
      var tamMeta = window.AIO_INDUSTRY_TAM_REGISTRY[sicCode];
      if (tamMeta) {
        industryName = tamMeta.name;
        if (tamMeta.tam && tamMeta.sourceUrl && tamMeta.observedAt) {
          tamEstimate = tamMeta.tam;
          cagrEstimate = tamMeta.cagr || null;
          indicators.push({ source: tamMeta.sourceUrl, observedAt: tamMeta.observedAt, industry: tamMeta.name, tam: tamMeta.tam, cagr: tamMeta.cagr || null, allowedUse:'reference' });
        } else {
          indicators.push({ source: 'SEC SIC ' + sicCode, industry: tamMeta.name, status:'numeric-withheld', note:'시장규모 출처·기준일 미검증' });
        }
      } else {
        indicators.push({ source: 'SEC SIC ' + sicCode, note: 'TAM_REGISTRY 미매핑 — 산업별 TAM 추정 불가' });
      }
    }
  } catch(_secErr) {}
  // 소스 2: SCREENER_DB.memo에서 "TAM:" 패턴 grep
  var db = typeof _aioGetCanonicalScreenerRows === 'function' ? _aioGetCanonicalScreenerRows() : [];
  var row = db.find && db.find(function(r){ return r.sym === ticker; });
  if (row && row.memo) {
    var memoProvenanceReady = !!(row.memoSourceUrl && row.memoObservedAt);
    var tamMatch = String(row.memo).match(/TAM[:\s]*\$?([\d,.\sBTM조억]+)/i);
    if (tamMatch) {
      var memoTam = tamMatch[1].trim();
      if (memoProvenanceReady) {
        if (!tamEstimate) tamEstimate = memoTam;
        indicators.push({ source: row.memoSourceUrl, observedAt: row.memoObservedAt, extracted: memoTam, allowedUse:'reference' });
      } else {
        indicators.push({ source:'SCREENER_DB.memo', status:'numeric-withheld', note:'TAM 패턴은 있으나 출처·기준일 미검증' });
      }
    }
    var cagrMatch = String(row.memo).match(/CAGR[:\s]*([\d.]+%)/i);
    if (cagrMatch) {
      if (memoProvenanceReady) {
        if (!cagrEstimate) cagrEstimate = cagrMatch[1];
        indicators.push({ source: row.memoSourceUrl, observedAt: row.memoObservedAt, extracted: cagrMatch[1], allowedUse:'reference' });
      }
    }
  }
  var confidence = tamEstimate ? 'source-bounded-reference' : 'unavailable';
  var resp = {
    ticker: ticker,
    available: !!tamEstimate,
    sicCode: sicCode,
    industryName: industryName,
    tamEstimate: tamEstimate,
    cagrEstimate: cagrEstimate,
    indicators: indicators,
    dataConfidence: confidence,
    source: 'source-provenance-required',
    sourceKind: tamEstimate ? 'REFERENCE' : 'UNAVAILABLE',
    allowedUse: tamEstimate ? 'reference' : 'none',
    note: tamEstimate ? '출처와 기준일이 있는 산업 참고값이며 회사별 점유 가능 시장과 동일하지 않습니다.' : '출처·기준일이 검증된 시장규모가 없어 숫자를 표시하지 않습니다.'
  };
  window._tamCache[ticker] = { data: resp, ts: Date.now() };
  return resp;
};

// (7) fetchSEC13F: bounded ticker reverse lookup — SEC rows + unverified
// reference CUSIP crosswalk. A missing match is not absence of ownership.
window.AIO.fetchSEC13F = async function(ticker) {
  if (!ticker) return null;
  ticker = ticker.toUpperCase().trim();
  var queryUrl = 'https://efts.sec.gov/LATEST/search-index?q=' + encodeURIComponent(ticker) + '&forms=13F-HR';
  var whaleWisdomUrl = 'https://whalewisdom.com/stock/' + encodeURIComponent(ticker.toLowerCase());
  try {
    window._aio13fReferenceIndexPromise = window._aio13fReferenceIndexPromise || (typeof fetchWithTimeout === 'function'
      ? fetchWithTimeout('./public-data/masters/ticker-index-reference.json', {}, 12000).then(function(response) {
          if (!response || !response.ok) throw new Error('13F reference index HTTP ' + (response && response.status || 'error'));
          return response.json();
        })
      : Promise.resolve().then(function() {
          var fetchMethod = window.fetch || globalThis.fetch;
          if (typeof fetchMethod !== 'function') throw new Error('13F reference index fetch unavailable');
          return fetchMethod.call(window, './public-data/masters/ticker-index-reference.json');
        }).then(function(response) {
          if (!response || !response.ok) throw new Error('13F reference index HTTP ' + (response && response.status || 'error'));
          return response.json();
        }));
    var index = await window._aio13fReferenceIndexPromise;
    if (!index || index.schema !== 'masters-13f-reference-ticker-index.v1' || index.status !== 'REFERENCE_ONLY') {
      return { ticker: ticker, available: false, reason: '13F ticker index is not in an allowed reference-only state', queryUrl: queryUrl, whaleWisdomUrl: whaleWisdomUrl };
    }
    var record = (index.records || []).find(function(item) { return item && item.tickerReference === ticker; });
    var base = {
      ticker: ticker,
      available: true,
      matched: !!record,
      source: 'SEC EDGAR rows + reference CUSIP crosswalk',
      sourceKind: index.sourceKind || 'SEC_EDGAR_DERIVED_REFERENCE',
      status: index.status,
      mappingStatus: record ? record.mappingStatus : 'NOT_MAPPED',
      queryUrl: queryUrl,
      whaleWisdomUrl: whaleWisdomUrl,
      reviewedAt: index.reviewedAt || null,
      latestAvailablePeriod: index.latestAvailablePeriod || null,
      coverage: index.coverage || null,
      note: '13F는 분기 말 보고 행이며 제출 지연이 있습니다. tickerReference는 SEC 원문 필드가 아닌 검증 전 crosswalk입니다 (tickerReference is not SEC-provided). 이 결과는 현재 보유·실제 체결·전체 자산·매매 신호가 아닙니다.'
    };
    if (!record) {
      base.rows = [];
      base.verdict = 'reference-mapping-not-found';
      base.note += ' 이 bounded index에 매핑된 행이 없으며, underlying 13F 전체 행에 해당 종목이 없다는 뜻은 아닙니다.';
      return base;
    }
    base.rows = (record.rows || []).slice(0, 24);
    base.cusips = record.cusips || [];
    base.issuerReferences = record.issuerReferences || [];
    base.verdict = 'reference-rows-found';
    return base;
  } catch (error) {
    window._aio13fReferenceIndexPromise = null;
    return { ticker: ticker, available: false, reason: '13F reference index fetch failed', detail: error && error.message ? error.message : String(error), queryUrl: queryUrl, whaleWisdomUrl: whaleWisdomUrl };
  }
};

// 보조 (8): fetchSECRecentFilings — 최근 8-K (event-driven 파트너십/M&A)
// v49.57 P317 보강: URL 제공 → 실제 8-K 최근 5건 fetch+parse (filingDate, items, accession)
// raw.filings.recent에서 form==='8-K' 인덱스 추출. 학습 데이터 환각 차단 (M&A/CEO 변경 등 이벤트)
window.AIO.fetchSECRecentFilings = async function(ticker, opts) {
  opts = opts || {};
  if (!ticker) return null;
  ticker = ticker.toUpperCase().trim();
  // v49.65 P346: opts.max8K로 캐시 키 분리 + max 갯수 가변 (기본 5, partnership 40 등). max8K 변수는 아래에서 fetch 시 재선언 사용.
  var maxCount = (opts.max8K && opts.max8K > 0) ? Math.min(80, opts.max8K) : 5;
  opts.max8K = maxCount;  // downstream에서 동일 값 보장
  // 캐시 5분 (max 갯수별 분리)
  window._secFilingsCache = window._secFilingsCache || {};
  var cacheKey = ticker + '_max' + maxCount;
  var cached = window._secFilingsCache[cacheKey];
  if (cached && (Date.now() - cached.ts < 5 * 60 * 1000)) return cached.data;
  var biz = await window.AIO.fetchSECBusinessDescription(ticker);
  if (!biz || !biz.available) {
    var failResp = { ticker: ticker, available: false, reason: 'CIK 미등록 또는 SEC fetch 실패' };
    window._secFilingsCache[cacheKey] = { data: failResp, ts: Date.now() };
    return failResp;
  }
  // CIK 기반 직접 raw fetch — fetchSECBusinessDescription와 동일 endpoint
  try {
    var url = 'https://data.sec.gov/submissions/CIK' + biz.cik + '.json';
    // P1758: data.sec.gov is on the shared Worker allowlist, so the relay chain tries the Worker before any public
    // relay (corsproxy.io answered 403 to this origin on every request).
    for (var i = 0; i < 1; i++) {
      try {
        var raw = await fetchViaProxy(url, { parseJson: true, timeout: 10000 });
        if (raw) {
          if (raw && raw.filings && raw.filings.recent) {
            var rec = raw.filings.recent;
            var forms = rec.form || [];
            var recent8K = [];
            var max8K = opts.max8K || 5;
            for (var j = 0; j < forms.length && recent8K.length < max8K; j++) {
              if (forms[j] === '8-K') {
                recent8K.push({
                  filingDate: rec.filingDate[j],
                  reportDate: rec.reportDate ? rec.reportDate[j] : null,
                  accession: rec.accessionNumber[j],
                  primaryDoc: rec.primaryDocument[j],
                  items: rec.items ? rec.items[j] : null,
                  url: 'https://www.sec.gov/Archives/edgar/data/' + parseInt(biz.cik, 10) + '/' + (rec.accessionNumber[j] || '').replace(/-/g, '') + '/' + (rec.primaryDocument[j] || '')
                });
              }
            }
            var resp = {
              ticker: ticker,
              available: true,
              source: 'SEC EDGAR /submissions',
              cik: biz.cik,
              companyName: biz.companyName,
              recent8KList: recent8K,
              recent8KCount: recent8K.length,
              inspected8KLimit: max8K,
              browseUrl: 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=' + biz.cik + '&type=8-K&dateb=&owner=include&count=20',
              note: '8-K는 event-driven 공시 (M&A/파트너십/CEO 변경/사이버 사고/실적 사전 공시 등). Items 코드: 1.01=계약/2.02=실적/5.02=임원변경/7.01=Reg FD/8.01=기타.'
            };
            window._secFilingsCache[cacheKey] = { data: resp, ts: Date.now() };
            return resp;
          }
        }
      } catch(_proxyErr) {}
    }
  } catch(e) {}
  var failResp2 = { ticker: ticker, available: false, reason: 'SEC 8-K fetch 실패 — 프록시 모두 fail' };
  window._secFilingsCache[cacheKey] = { data: failResp2, ts: Date.now() };
  return failResp2;
};

