// ─────────────────────────────────────────────────────────────────
// v49.27 E1/E2 근본 수정: ACTION_RULES — 시장 환경별 Action Item 단일 정의
// home/briefing의 "지금 해야 할 일" 가이드 부재 해소.
// VIX·F&G 구간별 포지션 사이즈 + 헤지 규칙을 코드로 명시.
// ─────────────────────────────────────────────────────────────────
window.AIO_ACTION_RULES = {
  version: 'v53.1',
  // P714: 이 객체는 v49.27까지 "포지션 X%로 축소/풋 헤지 필수/역발상 매수" 같은 시스템 발화형
  // 배분·매매 지시를 정적 렌더했다. 입력(VIX/F&G 절대 밴드)의 예측력이 검증된 적 없고(WO-2는
  // 유사 입력 계열에서 음의 상관), AI 채팅 게이트는 동일 문형을 차단한다 — 정적 UI만 예외일 수
  // 없다. 전 문구를 관측 서술로 재작성했고, P1557에서 sizePct 자체를 규칙에서 제거했다.
  // P1557: the ladder uses the same 18 / 25 / 32 edges and names as RULES.volatility and vixRegime (parity: ci-domain-parity-check). The
  // old 15 / 20 / 25 / 30 edges disagreed with the VIX status on the same card, and the sizePct values (100/80/50/30/15) were printed
  // as "포지션 N%" on the home and briefing pages; there is no position size in the rules any more.
  positionSizing: {
    rules: [
      { vixMax: 18, label: '저변동 구간', note: 'VIX 18 미만 — 변동성이 낮은 구간입니다.' },
      { vixMax: 25, label: '통상 범위', note: 'VIX 18~25 — 통상 범위의 변동성입니다.' },
      { vixMax: 32, label: '변동성 경계 구간', note: 'VIX 25~32 — 변동성이 커진 경계 구간입니다. 손실 한도와 보유 종목의 변동은 본인 기준으로 확인할 항목입니다.' },
      { vixMax: Infinity, label: '고변동 구간', note: 'VIX 32 이상 — 변동성이 매우 큰 구간입니다. 현금·헤지·신규 진입 여부는 본인 기준으로 확인할 항목입니다.' }
    ],
    getRule: function(vix) {
      if (vix == null || vix === '' || !isFinite(Number(vix))) return null;
      var v = Number(vix);
      for (var i = 0; i < this.rules.length; i++) if (v < this.rules[i].vixMax) return this.rules[i];
      return this.rules[this.rules.length - 1];
    }
  },
  // F&G 구간 관측 (행동 지시가 아니라 심리 구간 서술)
  sentimentAction: {
    rules: [
      { fgMax: 25, action: '극단 공포 구간', note: '심리가 극단적으로 위축된 구간입니다. F&G 밴드 자체의 예측력은 검증되지 않았고, 종목별 근거는 따로 확인할 항목입니다.' },
      { fgMax: 45, action: '공포 구간',     note: '심리가 위축된 구간입니다. 종목별 근거가 우선입니다.' },
      { fgMax: 56, action: '중립 구간',     note: '뚜렷한 심리 쏠림 없음.' },
      { fgMax: 76, action: '탐욕 구간',     note: '심리가 과열 쪽으로 기운 구간입니다. 예측 신호가 아닙니다.' },
      { fgMax: 101, action: '극단 탐욕 구간', note: '심리가 극단적으로 과열된 구간입니다. F&G 밴드 자체의 예측력은 검증되지 않았습니다.' }
    ],
    getRule: function(fg) {
      if (fg == null || fg === '' || !isFinite(Number(fg))) return null;
      var v = Math.round(Number(fg)); // P1534: CNN publishes whole numbers; fgMax 56/76 make 55 neutral and 75 greed
      for (var i = 0; i < this.rules.length; i++) if (v < this.rules[i].fgMax) return this.rules[i];
      return this.rules[this.rules.length - 1];
    }
  },
  // 통합 환경 관측 요약 (VIX + F&G + breadth) — 매매 지시를 생성하지 않는다
  getActionPlan: function(env) {
    env = env || {};
    var pos = this.positionSizing.getRule(env.vix);
    var sent = this.sentimentAction.getRule(env.fg);
    var actions = [];
    if (pos) actions.push('변동성 환경(' + pos.label + '): ' + pos.note);
    if (sent) actions.push('심리 환경(' + sent.action + '): ' + sent.note);
    if (env.breadth50 != null) {
      var bn = Number(env.breadth50);
      if (bn < 30) actions.push('Breadth: 시장 참여 폭 협소 — 역사적으로 개별 종목 변동성이 지수 대비 커지던 환경.');
      else if (bn > 70) actions.push('Breadth: 광범위 참여 — 역사적으로 섹터 간 순환이 활발하던 환경.');
    }
    // v50.45 [자율 루프] 뉴스 인지 — 받아온 뉴스 감성/이벤트를 환경 요약에 반영(폴백: newsSignal 없으면 기존 동작).
    var newsTilt = null, ns = env.newsSignal;
    var minNewsSample = Number(window.AIO_ARCH && window.AIO_ARCH.MIN_NEWS_ANALYSIS_SAMPLE);
    var nsSampleSufficient = Number.isInteger(minNewsSample) && minNewsSample > 0
      && ns && ns.sampleSufficient === true && ns.decisionEligible === true && Number(ns.total) >= minNewsSample
      && typeof ns.sentimentScore === 'number' && Number.isFinite(ns.sentimentScore);
    if (ns && ns.available === true && ns.allowedUse === true && nsSampleSufficient) {
      if (ns.bias === 'bearish') { newsTilt = 'defensive'; actions.push('뉴스 환경: 부정 뉴스 우위(감성 ' + ns.sentimentScore + ') — 헤드라인 리스크가 큰 국면.'); }
      else if (ns.bias === 'bullish') { newsTilt = 'constructive'; actions.push('뉴스 환경: 긍정 뉴스 우위(감성 ' + ns.sentimentScore + ') — 과열 여부를 함께 볼 국면.'); }
      if (ns.eventFlags && ns.eventFlags.geopolitical) actions.push('지정학 뉴스 활성 — 이벤트 리스크 확인 필요.');
    }
    return { actions: actions, position: pos, sentiment: sent, newsTilt: newsTilt, generatedAt: new Date().toISOString() };
  }
};


// ─────────────────────────────────────────────────────────────────
// v49.25 L7 근본 수정: PIOTROSKI_CHECKLIST — F-Score 9 항목 자동 분류
// fundamental L8134~8142 "9가지 YES/NO 체크"를 데이터로 분류 + auto-score.
// ─────────────────────────────────────────────────────────────────
window.AIO_PIOTROSKI_CHECKLIST = {
  version: 'v49.25',
  categories: {
    profitability: [
      { id: 'positive_ni',     label: '양(+)의 순이익',              check: function(d){ return Number(d.netIncome) > 0; } },
      { id: 'positive_roa',    label: '양(+)의 ROA',                 check: function(d){ return Number(d.roa) > 0; } },
      { id: 'positive_cfo',    label: '양(+)의 영업현금흐름',          check: function(d){ return Number(d.cfo) > 0; } },
      { id: 'cfo_gt_ni',       label: '영업현금흐름 > 순이익 (이익 질)', check: function(d){ return Number(d.cfo) > Number(d.netIncome); } }
    ],
    leverage: [
      { id: 'lower_lt_debt',   label: '장기부채 비율 감소(YoY)',       check: function(d){ return Number(d.ltDebtPrev) > Number(d.ltDebt); } },
      { id: 'higher_curr_ratio', label: '유동비율 증가(YoY)',          check: function(d){ return Number(d.currRatio) > Number(d.currRatioPrev); } },
      { id: 'no_dilution',     label: '신주발행 없음 (희석 X)',         check: function(d){ return Number(d.shares) <= Number(d.sharesPrev); } }
    ],
    efficiency: [
      { id: 'higher_margin',   label: '매출총이익률 증가(YoY)',         check: function(d){ return Number(d.gpm) > Number(d.gpmPrev); } },
      { id: 'higher_turnover', label: '자산회전율 증가(YoY)',          check: function(d){ return Number(d.assetTurnover) > Number(d.assetTurnoverPrev); } }
    ]
  },
  // d = financial data object with above keys
  score: function(d) {
    var details = [];
    var total = 0;
    var self = this;
    Object.keys(this.categories).forEach(function(cat) {
      self.categories[cat].forEach(function(item) {
        var pass = false;
        try { pass = !!item.check(d || {}); } catch(_) { pass = false; }
        if (pass) total++;
        details.push({ category: cat, id: item.id, label: item.label, pass: pass });
      });
    });
    return {
      score: total,
      max: 9,
      details: details,
      verdict: total >= 8 ? '우수' : total >= 5 ? '양호' : total >= 3 ? '주의' : '위험'
    };
  }
};

