// ─────────────────────────────────────────────────────────────────
// v49.24 P213/P216/P218 근본 수정: getSnapshotConsistencyAudit
// 모든 [data-snap] 요소의 DOM 인라인 텍스트 vs DATA_SNAPSHOT 값 3-way 비교
// + 동일 data-snap key가 여러 페이지에 sink 등록되었는지(P216 패턴) 검사.
// 불일치 발견 시 issueCount > 0. v49.24 R55/R58 강제.
// ─────────────────────────────────────────────────────────────────
window.AIO.getSnapshotConsistencyAudit = function() {
  var issues = [];
  var sinkMap = {};   // data-snap key -> [elements...]
  var mismatches = []; // {key, expected (DATA_SNAPSHOT), found (DOM inline)}
  try {
    var S = window.DATA_SNAPSHOT || {};
    document.querySelectorAll('[data-snap]').forEach(function(el) {
      var key = el.getAttribute('data-snap');
      if (!key) return;
      sinkMap[key] = sinkMap[key] || [];
      sinkMap[key].push({
        text: (el.textContent || '').trim().slice(0, 80),
        pageId: (function() { var p = el.closest('[id^="page-"]'); return p ? p.id : null; })()
      });
    });
    // applyDataSnapshot의 map 결과와 비교는 직접 불가 — 대신 같은 key가 여러 sink에서 다른 텍스트 나타나면 즉시 불일치
    Object.keys(sinkMap).forEach(function(key) {
      var sinks = sinkMap[key];
      if (sinks.length < 2) return;
      var uniqueTexts = {};
      sinks.forEach(function(s) { uniqueTexts[s.text] = (uniqueTexts[s.text] || 0) + 1; });
      var distinct = Object.keys(uniqueTexts);
      if (distinct.length > 1) {
        mismatches.push({ key: key, sinkCount: sinks.length, distinctValues: distinct, sinks: sinks });
        issues.push('sink-mismatch: ' + key + ' has ' + distinct.length + ' distinct values across ' + sinks.length + ' sinks');
      }
    });
  } catch (e) {
    issues.push({ type: 'audit-error', message: e && e.message || String(e) });
  }
  return {
    status: issues.length ? 'warn' : 'ok',
    issueCount: issues.length,
    issues: issues,
    sinkKeys: Object.keys(sinkMap).length,
    totalSinks: Object.keys(sinkMap).reduce(function(n, k) { return n + sinkMap[k].length; }, 0),
    mismatches: mismatches,
    generatedAt: new Date().toISOString()
  };
};


// ─────────────────────────────────────────────────────────────────
// v49.25 L3 근본 수정: diagnoseBreadthConsensus
// 다중 신호(5SMA/20SMA/50SMA/McClellan/Weinstein/Golden Cross)를 가중 평균하여
// 합의된 단일 판정을 도출. 모순 시그널 자동 가중치 조정.
// ─────────────────────────────────────────────────────────────────
window.AIO.diagnoseBreadthConsensus = function(signals) {
  signals = signals || {};
  var reg = window.AIO_THRESHOLD_REGISTRY;
  if (!reg || !reg.BREADTH) return { verdict: '—', score: null, conflict: null };

  var weights = { sma5: 0.10, sma20: 0.20, sma50: 0.30, mcclellan: 0.20, weinstein: 0.10, goldenCross: 0.10 };
  var totalWeight = 0, totalScore = 0;
  var details = [];
  // signal bands: bullish=+1, mixed=0, bearish=-1, capitulation=+0.5, overbought=-0.5
  var bandScoreMap = { 'capitulation': 0.5, 'bearish': -1, 'mixed': 0, 'bullish': 1, 'overbought': -0.5 };

  ['sma5', 'sma20', 'sma50'].forEach(function(k) {
    var v = Number(signals[k]);
    if (isNaN(v)) return;
    var label = reg.BREADTH.getLabel(v);
    var score = bandScoreMap[label.signal] != null ? bandScoreMap[label.signal] : 0;
    totalScore += score * weights[k];
    totalWeight += weights[k];
    details.push({ key: k, value: v, label: label.label, score: score });
  });

  // 추가 신호: 'bullish' | 'bearish' | 'neutral' 직접 입력
  ['mcclellan', 'weinstein', 'goldenCross'].forEach(function(k) {
    if (signals[k] == null) return;
    var s = signals[k];
    var score = s === 'bullish' ? 1 : s === 'bearish' ? -1 : 0;
    totalScore += score * weights[k];
    totalWeight += weights[k];
    details.push({ key: k, signal: s, score: score });
  });

  if (totalWeight === 0) return { verdict: '—', score: null, conflict: null };
  var consensus = totalScore / totalWeight;
  var verdict;
  if (consensus > 0.4) verdict = '강세 합의';
  else if (consensus > 0.1) verdict = '강세 우위';   // v50.20: 부호 버그 시정 — 양의 합의(0.1~0.4)는 강세 우위 (이전 '약세 우위'는 결론 반대)
  else if (consensus > -0.1) verdict = '혼조 (모순 신호 존재)';
  else if (consensus > -0.4) verdict = '약세 우위';
  else verdict = '약세 합의';

  // 모순 탐지: 각 시그널의 부호가 다를 때
  var positives = details.filter(function(d) { return d.score > 0; }).length;
  var negatives = details.filter(function(d) { return d.score < 0; }).length;
  var conflict = positives > 0 && negatives > 0
    ? { positiveCount: positives, negativeCount: negatives, note: positives + '개 강세 vs ' + negatives + '개 약세 신호 공존' }
    : null;

  return {
    verdict: verdict,
    consensus: consensus,
    details: details,
    conflict: conflict
  };
};

// ─────────────────────────────────────────────────────────────────
// v49.25 R56 자동화: getThresholdLabelAudit
// THRESHOLD_REGISTRY에 등록된 지표의 라벨(예: '극단 공포', 'Tight')이
// DOM에 인라인 텍스트로 직접 작성된 위치를 탐지 → registry 미경유 위치 보고.
// ─────────────────────────────────────────────────────────────────
window.AIO.getThresholdLabelAudit = function() {
  var reg = window.AIO_THRESHOLD_REGISTRY;
  if (!reg) return { status: 'error', message: 'AIO_THRESHOLD_REGISTRY undefined', issueCount: 0, issues: [] };

  // 모든 등록된 라벨 모음
  var allLabels = {};
  Object.keys(reg).forEach(function(key) {
    if (!reg[key].bands) return;
    reg[key].bands.forEach(function(b) {
      if (b.label && b.label !== '—') {
        allLabels[b.label] = allLabels[b.label] || [];
        allLabels[b.label].push(key);
      }
    });
  });

  var issues = [];
  var inlineHits = [];
  try {
    // 모든 페이지 텍스트에서 라벨 검색
    var pages = document.querySelectorAll('[id^="page-"]');
    pages.forEach(function(page) {
      // archive 섹션 제외
      var clone = page.cloneNode(true);
      clone.querySelectorAll('[data-aio-archive="true"]').forEach(function(el) { el.remove(); });
      var txt = (clone.textContent || '');
      Object.keys(allLabels).forEach(function(label) {
        // 정확히 일치하는 인라인 라벨 (tooltip/설명 외)
        var count = (txt.match(new RegExp(label.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&'), 'g')) || []).length;
        if (count > 0) {
          inlineHits.push({ page: page.id, label: label, count: count, registries: allLabels[label] });
        }
      });
    });
    // tooltip/정의문 내부는 합법적 → 정보성으로만 보고
  } catch (e) {
    issues.push({ type: 'audit-error', message: e && e.message || String(e) });
  }

  return {
    status: 'ok',
    issueCount: issues.length,
    issues: issues,
    registryLabels: Object.keys(allLabels).length,
    inlineHits: inlineHits.length,
    sampleHits: inlineHits.slice(0, 20),
    note: 'inlineHits 수가 많을수록 R56 위반 가능성 증가. 라벨이 getLabel() 경유하는지 코드 리뷰 필요.',
    generatedAt: new Date().toISOString()
  };
};


// ─────────────────────────────────────────────────────────────────
// v49.26 I7 근본 수정: getCycleFromMacro
// 경기 사이클 위치를 매크로 지표(VIX/breadth/yield curve)로부터 동적 판정.
// themes 페이지의 "◀ 현재(Late Cycle)" 정적 고정 해소.
// ─────────────────────────────────────────────────────────────────
window.AIO.getCycleFromMacro = function(macro) {
  macro = macro || {};
  var ld = window._liveData || {};
  var vix = _aioStrictFinite(macro.vix != null ? macro.vix : (ld['^VIX'] ? ld['^VIX'].price : NaN));
  var breadthEvidence = window.AIO && typeof window.AIO.getCurrentBreadthEvidence === 'function' ? window.AIO.getCurrentBreadthEvidence() : { available:false };
  var breadthCandidate = macro.breadth50 != null ? _aioStrictFinite(macro.breadth50) : (breadthEvidence.available ? _aioStrictFinite(breadthEvidence.sma50) : NaN);
  var breadth50 = Number.isFinite(breadthCandidate) && breadthCandidate >= 0 && breadthCandidate <= 100 ? breadthCandidate : NaN;
  var yieldCandidate = macro.yield2s10s;
  var yield2s10s = _aioStrictFinite(yieldCandidate);
  var liveSpxPct = ld['^GSPC'] ? _aioStrictFinite(ld['^GSPC'].pct) : null;
  // Owner 2026-10-18: the 시장 상태 trend axis decides (양호 up · 부담 down · 중립 none); one session's sign only without a regime.
  var rs = null; try { rs = typeof window._aioMarketRegimeSummary === 'function' ? window._aioMarketRegimeSummary() : null; } catch (_) {} var rt = rs && rs.available && rs.trend !== 'unknown' ? rs.trend : null;
  var spxTrend = macro.spxTrend === 'up' || macro.spxTrend === 'down' ? macro.spxTrend : rt ? (rt === 'favorable' ? 'up' : rt === 'burden' ? 'down' : null) : liveSpxPct == null ? null : liveSpxPct > 0 ? 'up' : 'down';

  var rationale = [];
  // v50.46 [알고리즘 재작성] 단순 의사결정 트리 → 정규화·가중 다신호 모델.
  //   각 신호를 -1(악화)~+1(건강)로 정규화(중심·스케일=역사적 정상범위) → 가중합 → cyclePos 0~100(경기 위치).
  //   곡선 역전은 별도 침체-선행 신호로 가중. 기존 phase 라벨 어휘 보존(themes 페이지/테스트 호환) + score/confidence/components 추가.
  function _clamp1(x){ return x < -1 ? -1 : x > 1 ? 1 : x; }
  var hasVix = Number.isFinite(vix) && vix >= 0, hasBreadth = Number.isFinite(breadth50);
  var hasCurve = yield2s10s != null, hasTrend = spxTrend === 'up' || spxTrend === 'down';
  if (!hasBreadth) {
    return {
      phase: '판정 보류', score: null, confidence: 'low',
      inputs: { vix: hasVix ? vix : null, breadth50: null, yield2s10s: yield2s10s, spxTrend: spxTrend },
      rationale: ['기준 시각이 확인된 50일선 시장폭 근거 미수신 · 경기 사이클 판정 보류'],
      generatedAt: new Date().toISOString()
    };
  }
  if (!hasVix && !hasCurve && !hasTrend) {
    return { phase: '판정 보류', score: null, confidence: 'low', inputs: { vix: null, breadth50: breadth50, yield2s10s: null, spxTrend: null }, rationale: ['시장폭 외 보조 근거 미수신 · 경기 사이클 판정 보류'], generatedAt: new Date().toISOString() };
  }
  var nVix = hasVix ? _clamp1((20 - vix) / 12) : 0;            // VIX 8→+1(안정), 32→-1(패닉), 20→0
  var nBreadth = hasBreadth ? _clamp1((breadth50 - 50) / 28) : 0; // 78%→+1, 22%→-1, 50%→0
  var nCurve = hasCurve ? _clamp1(yield2s10s / 1.2) : 0;       // +1.2%p→+1(가파른 정상), 역전→음
  var nTrend = spxTrend === 'up' ? 0.5 : spxTrend === 'down' ? -0.5 : 0;
  var W = { breadth: 0.30, vix: 0.30, trend: 0.25, curve: 0.15 };  // 시장폭·변동성 우선, 추세·곡선 보조
  var raw = nBreadth * W.breadth + nVix * W.vix + nTrend * W.trend + nCurve * W.curve; // -1..+1
  var cyclePos = Math.round((raw + 1) * 50); // 0..100
  var inverted = hasCurve && yield2s10s < 0;
  var present = (hasVix ? 1 : 0) + (hasBreadth ? 1 : 0) + (hasCurve ? 1 : 0) + (hasTrend ? 1 : 0);

  var phase;
  if (inverted && nVix < 0) {
    phase = '환경 약화';
    rationale.push('수익률 곡선 역전(2s10s ' + yield2s10s.toFixed(2) + ')과 변동성 상승 동시 관측');
  } else if (cyclePos >= 72 && nTrend > 0 && nVix > 0.2) {
    phase = '환경 양호';
    rationale.push('낮은 변동성·넓은 시장폭·상승 추세');
  } else if (cyclePos >= 55) {
    phase = '환경 양호';
    rationale.push('시장폭·변동성 양호');
  } else if (cyclePos >= 42 && nTrend > 0) {
    phase = '지표 혼재';
    rationale.push('약한 시장폭과 상승 추세 동시 관측');
  } else if (cyclePos >= 30) {
    phase = '지표 혼재';
    rationale.push('입력 방향 혼재');
  } else if (nTrend < 0 && nVix < -0.2) {
    phase = '환경 약화';
    rationale.push('하락 추세와 높은 변동성');
  } else {
    phase = '환경 약화';
    rationale.push('시장폭·변동성 약화');
  }
  if (inverted) rationale.push('수익률 곡선 역전 관측 · 경기 국면 확정 근거가 아닙니다');

  return {
    phase: phase,
    score: cyclePos,
    confidence: present >= 3 ? 'high' : present >= 2 ? 'medium' : 'low',
    inputs: { vix: vix, breadth50: breadth50, yield2s10s: yield2s10s, spxTrend: spxTrend },
    components: { vix: Number(nVix.toFixed(2)), breadth: Number(nBreadth.toFixed(2)), trend: nTrend, curve: Number(nCurve.toFixed(2)) },
    rationale: rationale,
    generatedAt: new Date().toISOString()
  };
};


window.AIO.recordDataQualityIssue = function(issue) {
  try {
    window._aioDataQualityIssues = window._aioDataQualityIssues || [];
    var item = Object.assign({
      ts: Date.now(),
      severity: 'warn',
      source: 'unknown',
      message: 'data quality issue'
    }, issue || {});
    window._aioDataQualityIssues.push(item);
    if (window._aioDataQualityIssues.length > 120) window._aioDataQualityIssues = window._aioDataQualityIssues.slice(-120);
    if (typeof _aioLog === 'function') _aioLog(item.severity === 'error' ? 'error' : 'warn', 'data-quality', item.source + ': ' + item.message);
  } catch(_) {}
};

window.AIO.getDataQualityIssueAudit = function(opts) {
  opts = opts || {};
  var horizonMs = opts.horizonMs || 6 * 3600000;
  var now = Date.now();
  var issues = (window._aioDataQualityIssues || []).filter(function(x) {
    return x && (!x.ts || now - x.ts <= horizonMs);
  });
  var blocking = issues.filter(function(x) { return x.severity === 'error' || x.blocking === true; });
  return {
    status: blocking.length ? 'fail' : (issues.length ? 'warn' : 'ok'),
    issueCount: issues.length,
    blockingCount: blocking.length,
    issues: issues,
    generatedAt: new Date(now).toISOString()
  };
};

window.AIO.getSnapshotDateSourceAudit = function() {
  var issues = [];
  var items = [];
  try {
    document.querySelectorAll('[data-snap-date]').forEach(function(el) {
      var key = el.getAttribute('data-snap-date') || '';
      var val = (el.textContent || '').trim();
      var explicit = el.getAttribute('data-snap-date-value') || '';
      var hasRegistry = !!(window.DATA_SNAPSHOT && window.DATA_SNAPSHOT._staticDates && (
        key === 'cp-narrative' || key === 'tnx-2y' ||
        key === 'briefing-archive' || key === 'jensen-interview' ||
        key === 'option-snapshot' || key === 'kr-credit' || key === 'kr-deposit' ||
        key === 'kr-52w-high' || key === 'kr-52w-low' || key === 'kr-advance' ||
        key === 'kr-decline' || key === 'kr-issues'
      ));
      items.push({ key: key, value: val, explicit: explicit, registered: hasRegistry });
      if (key === 'option-snapshot' && val === (window.DATA_SNAPSHOT && window.DATA_SNAPSHOT._snapshotDate)) {
        issues.push({ type: 'date-source-collapsed-to-global-snapshot', key: key, value: val });
      }
    });
  } catch(e) {
    issues.push({ type: 'audit-error', message: e && e.message || String(e) });
  }
  return {
    status: issues.length ? 'warn' : 'ok',
    issueCount: issues.length,
    issues: issues,
    items: items,
    generatedAt: new Date().toISOString()
  };
};

// v50.79: runtime contract gate.
// It catches the failure class where UI edits remove or rename runtime callables
// while AI prompts, digest artifacts, or cachebusters still depend on them.
window.AIO.getRuntimeContractAudit = function() {
  var failures = [];
  var warnings = [];
  var scripts = [];
  try {
    scripts = Array.prototype.slice.call(document.scripts || [])
      .map(function(s) { return s.getAttribute('src') || ''; })
      .filter(Boolean);
  } catch(_) {}

  function requireFn(name, owner) {
    var ok = typeof window[name] === 'function';
    if (!ok) failures.push((owner || 'runtime') + ' callable missing: ' + name);
    return ok;
  }
  function requireAioFn(name, owner) {
    var ok = !!(window.AIO && typeof window.AIO[name] === 'function');
    if (!ok) failures.push((owner || 'AIO') + ' method missing: AIO.' + name + '()');
    return ok;
  }

  var ver = (window.AIO && window.AIO.version) || (typeof APP_VERSION === 'string' ? APP_VERSION : '');
  var verNum = String(ver || '').replace(/^v/, '');
  var jsScripts = scripts.filter(function(src) { return /\/?js\/aio-/.test(src); });
  var wrongBusters = verNum ? jsScripts.filter(function(src) {
    var m = src.match(/\?v=([\d.]+)/);
    return m && m[1] !== verNum;
  }) : [];
  if (wrongBusters.length) failures.push('JS cachebuster drift: ' + wrongBusters.join(', '));
  if (jsScripts.length && verNum && jsScripts.filter(function(src) { return src.indexOf('?v=' + verNum) >= 0; }).length < 5) {
    warnings.push('expected five versioned aio JS scripts; found ' + jsScripts.length);
  }

  requireFn('_aioCreateVisualReport', 'AI visual report');
  requireFn('_aioDownloadVisualReport', 'AI visual report');
  requireFn('_getImportedResearchContext', 'AI imported research');
  requireAioFn('applyUserResearchDigestPayload', 'research digest');
  requireAioFn('loadUserResearchDigest', 'research digest');
  requireAioFn('getUserResearchPipelineAudit', 'research digest');

  var digestContract = window.AIO_USER_RESEARCH_REFRESH_CONTRACT || {};
  if (digestContract.sourceKind !== 'REFERENCE') failures.push('user research digest must remain sourceKind=REFERENCE');
  if (digestContract.uiPolicy !== 'data-only-no-premium-board') failures.push('user research digest uiPolicy drift');
  if (!digestContract.digestPath) warnings.push('user research digest path unavailable');

  var digestAudit = window.AIO && window.AIO.getUserResearchPipelineAudit ? window.AIO.getUserResearchPipelineAudit() : null;
  if (!digestAudit) failures.push('user research pipeline audit unavailable');
  else {
    if (digestAudit.sourceKind !== 'REFERENCE') failures.push('user research audit sourceKind drift: ' + digestAudit.sourceKind);
    if (digestAudit.canPromoteToLive !== false) failures.push('REFERENCE research canPromoteToLive must be false');
    if (digestAudit.uiPolicy !== 'data-only-no-premium-board') failures.push('research digest must not recreate premium-board UI');
    if (digestAudit.status === 'unavailable') warnings.push('user research digest unavailable: ' + (digestAudit.detail || digestAudit.digestPath || 'unknown'));
  }

  var fakeUi = 0;
  try {
    fakeUi = document.querySelectorAll('.aio-premium-board,.aio-research-bridge,.apb-board').length;
  } catch(_) {}
  if (fakeUi) failures.push('removed fake research UI visible: ' + fakeUi + ' node(s)');

  return {
    status: failures.length ? 'fail' : (warnings.length ? 'warn' : 'ok'),
    failureCount: failures.length,
    warningCount: warnings.length,
    failures: failures,
    warnings: warnings,
    version: ver || null,
    scriptCount: jsScripts.length,
    digest: digestAudit,
    generatedAt: new Date().toISOString()
  };
};

window.AIO.getDeploymentGateAudit = function(opts) {
  opts = opts || {};
  var strict = opts.strict !== false;
  var mode = opts.mode === 'runtime' ? 'runtime' : 'full';
  var readiness = opts.readiness || (window.AIO.getAutoOpsReadiness ? window.AIO.getAutoOpsReadiness({ mode: mode }) : null);
  var hardcoded = readiness && readiness.hardcodedQuoteFallback || (window.AIO.getHardcodedQuoteFallbackAudit ? window.AIO.getHardcodedQuoteFallbackAudit() : null);
  var snapGuard = readiness && readiness.snapshotFallbackGuard || (window.AIO.getSnapshotFallbackGuard ? window.AIO.getSnapshotFallbackGuard() : null);
  var macro = readiness && readiness.macroRelease || (window.AIO.getMacroReleaseStaleAudit ? window.AIO.getMacroReleaseStaleAudit() : null);
  var krMacro = readiness && readiness.krMacroRelease || (window.AIO.getKrMacroReleaseAudit ? window.AIO.getKrMacroReleaseAudit() : null);
  var dataQuality = readiness && readiness.dataQuality || (window.AIO.getDataQualityIssueAudit ? window.AIO.getDataQualityIssueAudit() : null);
  var dateSources = readiness && readiness.snapshotDateSources || (window.AIO.getSnapshotDateSourceAudit ? window.AIO.getSnapshotDateSourceAudit() : null);
  var evidenceGate = mode === 'full' ? (readiness && readiness.evidenceDeploymentGate || null) : null;
  var essence = mode === 'full' && !opts.skipEssence ? (readiness && readiness.essenceAlignment || null) : null;
  var fullSurface = mode === 'full' ? (readiness && readiness.fullSurfaceAudit || null) : null;
  var deepReview = mode === 'full' ? (readiness && readiness.deepReviewAudit || null) : null;
  var fourthFifth = mode === 'full' ? (readiness && readiness.fourthFifthPass || null) : null;
  var runtimeContract = readiness && readiness.runtimeContract || (window.AIO.getRuntimeContractAudit ? window.AIO.getRuntimeContractAudit() : null);
  var blocking = [];
  var warnings = [];

  if (!readiness) blocking.push('auto-ops readiness unavailable');
  if (!hardcoded || hardcoded.status !== 'ok') blocking.push('hardcoded quote fallback reachable');
  if (snapGuard && snapGuard.usable === false) blocking.push('DATA_SNAPSHOT hard-stale; refresh snapshot before deploy');
  if (readiness && readiness.liveSymbolsCoverage && readiness.liveSymbolsCoverage.issueCount) blocking.push('LIVE_SYMBOLS coverage mismatch');
  if (readiness && readiness.dataActionHandler && readiness.dataActionHandler.issueCount) blocking.push('missing data-action handler');
  if (macro && macro.staleReleaseCount) warnings.push(macro.staleReleaseCount + ' stale US macro release(s)');
  if (krMacro && krMacro.krStaleReleaseCount) warnings.push(krMacro.krStaleReleaseCount + ' stale KR macro release(s)');
  if (dataQuality && dataQuality.blockingCount) blocking.push(dataQuality.blockingCount + ' blocking data quality issue(s)');
  if (dataQuality && dataQuality.issueCount && !dataQuality.blockingCount) warnings.push(dataQuality.issueCount + ' data quality warning(s)');
  if (dateSources && dateSources.issueCount) warnings.push(dateSources.issueCount + ' snapshot date source issue(s)');
  if (evidenceGate && evidenceGate.blocking && evidenceGate.blocking.length) blocking = blocking.concat(evidenceGate.blocking.map(function(x) { return 'v50 evidence gate: ' + x; }));
  if (evidenceGate && evidenceGate.warnings && evidenceGate.warnings.length) warnings = warnings.concat(evidenceGate.warnings.map(function(x) { return 'v50 evidence gate: ' + x; }));
  if (essence && essence.overallScore < 70) blocking.push('3대 본질 정렬 점수 70 미만');
  else if (essence && essence.status !== 'ok') warnings.push('3대 본질 정렬 warn: ' + essence.overallScore + '점');
  if (fullSurface && fullSurface.status === 'fail') blocking.push('full surface audit fail: ' + fullSurface.issueCount + ' issue(s)');
  else if (fullSurface && fullSurface.status !== 'ok') warnings.push('full surface audit warn: ' + fullSurface.issueCount + ' issue(s)');
  if (deepReview && deepReview.status === 'fail') blocking.push('deep review audit fail: ' + deepReview.issueCount + ' issue(s)');
  else if (deepReview && deepReview.status !== 'ok') warnings.push('deep review audit warn: ' + deepReview.warningCount + ' warning(s)');
  if (fourthFifth && fourthFifth.status === 'fail') blocking.push('fourth/fifth pass audit fail: ' + fourthFifth.issueCount + ' issue(s)');
  else if (fourthFifth && fourthFifth.status !== 'ok') warnings.push('fourth/fifth pass audit warn: ' + fourthFifth.warningCount + ' warning(s)');
  if (!runtimeContract) blocking.push('runtime contract audit unavailable');
  else if (runtimeContract.status === 'fail') blocking = blocking.concat(runtimeContract.failures.map(function(x) { return 'runtime contract: ' + x; }));
  else if (runtimeContract.status === 'warn') warnings = warnings.concat(runtimeContract.warnings.map(function(x) { return 'runtime contract: ' + x; }));
  if (strict && warnings.length) blocking = blocking.concat(warnings);

  return {
    status: blocking.length ? 'fail' : (warnings.length ? 'warn' : 'ok'),
    deployable: blocking.length === 0,
    strict: strict,
    mode: mode,
    blocking: blocking,
    warnings: warnings,
    readinessStatus: readiness && readiness.status || null,
    hardcodedQuoteFallback: hardcoded,
    snapshotFallbackGuard: snapGuard,
    macroRelease: macro,
    krMacroRelease: krMacro,
    dataQuality: dataQuality,
    snapshotDateSources: dateSources,
    evidenceDeploymentGate: evidenceGate,
    essenceAlignment: essence,
    fullSurfaceAudit: fullSurface,
    deepReviewAudit: deepReview,
    fourthFifthPass: fourthFifth,
    runtimeContract: runtimeContract,
    generatedAt: new Date().toISOString()
  };
};

window.AIO.getShareReadinessAudit = function(opts) {
  opts = opts || {};
  var deployment = opts.deployment || (window.AIO.getDeploymentGateAudit ? window.AIO.getDeploymentGateAudit({ strict: false, skipEssence: !!opts.skipEssence, readiness: opts.readiness }) : null);
  var runtime = window.AIO.getRuntimeContractAudit ? window.AIO.getRuntimeContractAudit() : null;
  var readiness = opts.readiness || (window.AIO.getAutoOpsReadiness ? window.AIO.getAutoOpsReadiness({ mode: 'runtime' }) : null);
  var blockers = [];
  var warnings = [];

  if (!deployment) blockers.push('deployment gate unavailable');
  else {
    blockers = blockers.concat((deployment.blocking || []).map(function(x) { return 'deployment: ' + x; }));
    warnings = warnings.concat((deployment.warnings || []).map(function(x) { return 'deployment: ' + x; }));
  }
  if (!runtime) blockers.push('runtime contract unavailable');
  else if (runtime.status === 'fail') blockers = blockers.concat(runtime.failures.map(function(x) { return 'runtime: ' + x; }));
  else if (runtime.status === 'warn') warnings = warnings.concat(runtime.warnings.map(function(x) { return 'runtime: ' + x; }));

  if (readiness && readiness.issues && readiness.issues.length) {
    warnings.push('auto-ops has ' + readiness.issues.length + ' warning(s); check AIO.getAutoOpsReadiness() before public sharing');
  }

  return {
    status: blockers.length ? 'not-shareable' : (warnings.length ? 'share-with-warnings' : 'shareable'),
    shareable: blockers.length === 0,
    blockers: blockers,
    warnings: warnings,
    nextActions: blockers.length
      ? ['Fix blockers before sharing externally.', 'Run node scripts/ci-version-check.mjs', 'Run node scripts/ci-runtime-contract-check.mjs']
      : (warnings.length ? ['Review warnings and label stale/REFERENCE data clearly.'] : ['Ready for external smoke review.']),
    runtimeContract: runtime,
    deploymentGate: deployment,
    readinessStatus: readiness && readiness.status || null,
    generatedAt: new Date().toISOString()
  };
};

