function _aioUniq(arr) {
  var seen = {};
  return (arr || []).filter(function(x) {
    x = String(x || '').trim();
    if (!x || seen[x]) return false;
    seen[x] = 1;
    return true;
  });
}

function _aioResolveRequirementProfile(pageId) {
  var map = window.AIO.DATA_REQUIREMENT_PROFILES || {};
  var id = String(pageId || '').replace(/^page-/, '') || 'home';
  var p = map[id] || null;
  if (p && p.alias) p = map[p.alias] || p;
  return p || { tasks: ['quotes'], symbols: [] };
}

function _aioPushSymbol(out, sym) {
  sym = String(sym || '').trim().toUpperCase();
  if (!sym || sym === 'NULL' || sym === 'N/A') return;
  out.push(sym);
}

function _aioBuildKrThemeSymbolIndex() {
  var index = {};
  function remember(sym) {
    sym = String(sym || '').trim().toUpperCase();
    var match = sym.match(/^(\d{6})\.(KS|KQ)$/);
    if (match && !index[match[1]]) index[match[1]] = sym;
  }
  try {
    (typeof _aioGetCanonicalScreenerRows === 'function' ? _aioGetCanonicalScreenerRows() : []).forEach(function(row) { remember(row && row.sym); });
    (window.KR_SUB_THEMES || []).forEach(function(theme) {
      (theme && theme.tickers || []).forEach(remember);
    });
  } catch (_) {}
  return index;
}

function _aioResolveKrThemeSymbol(raw, index) {
  raw = String(raw || '').trim().toUpperCase();
  if (!raw) return '';
  if (/\.(KS|KQ)$/.test(raw) || raw.indexOf('=') > 0 || raw.charAt(0) === '^') return raw;
  if (!/^\d{6}$/.test(raw)) return raw;
  if (index) return index[raw] || (raw + '.KS');
  try {
    var found = null;
    (typeof _aioGetCanonicalScreenerRows === 'function' ? _aioGetCanonicalScreenerRows() : []).some(function(r) {
      var sym = r && String(r.sym || '').toUpperCase();
      if (sym && sym.indexOf(raw + '.') === 0) {
        found = sym;
        return true;
      }
      return false;
    });
    if (found) return found;
    (window.KR_SUB_THEMES || []).some(function(t) {
      return (t.tickers || []).some(function(sym) {
        sym = String(sym || '').toUpperCase();
        if (sym.indexOf(raw + '.') === 0) {
          found = sym;
          return true;
        }
        return false;
      });
    });
    if (found) return found;
  } catch(_) {}
  return raw + '.KS';
}

function _aioPushThemeSymbols(out, theme) {
  if (!theme) return;
  _aioPushSymbol(out, theme.etf);
  _aioPushSymbol(out, theme.compositeBase);
  ['leaders', 'leaderHighlight', 'tickers'].forEach(function(key) {
    (theme[key] || []).forEach(function(sym) { _aioPushSymbol(out, sym); });
  });
  Object.keys(theme.weights || {}).forEach(function(sym) { _aioPushSymbol(out, sym); });
}

function _aioPushInputSymbol(out, id) {
  try {
    var el = document.getElementById(id);
    if (el && el.value) _aioPushSymbol(out, el.value);
  } catch(_) {}
}

function _aioCollectDynamicPageSymbols(pageId, scope) {
  var id = String(pageId || '').replace(/^page-/, '') || 'home';
  var out = [];
  var isThemePage = id === 'themes' || id === 'theme-detail';
  // v53.7 (P725): KR 테마 심볼은 이제 themes 페이지(통합 섹션)에서 수집 — KR 전용 라우트 퇴역
  var isKrThemePage = id === 'themes';
  var limit = (scope && scope.symbolLimit) || (isThemePage ? (isKrThemePage ? 900 : 650) : 260);
  if (id === 'signal') {
    _aioPushInputSymbol(out, 'signal-lockout-symbol');
  }
  if (id === 'technical') {
    // v57.76: the brief/TradingView ticker inputs were deleted; the 차트 tab shows the 종목 subject.
    _aioPushSymbol(out, window._aioLastOpenedSymbol);
  }
  if (id === 'fundamental' || id === 'ticker') {
    ['fund-search-input', 'ticker-analysis-input'].forEach(function(inputId) { _aioPushInputSymbol(out, inputId); });
  }
  if (id === 'themes' || id === 'theme-detail') {
    (window.RRG_SECTORS || []).forEach(function(sec) { _aioPushSymbol(out, sec && sec.sym); });
    (window.RRG_SUBSECTORS || []).forEach(function(sec) { _aioPushSymbol(out, sec && sec.sym); });
    (window.ALL_RRG_ETFS || []).forEach(function(sec) { _aioPushSymbol(out, sec && sec.sym); });
    (window.THEME_MAP || []).forEach(function(theme) { _aioPushThemeSymbols(out, theme); });
    (window.SUB_THEMES || []).forEach(function(theme) { _aioPushThemeSymbols(out, theme); });
  }
  if (isKrThemePage) {
    var krThemeSymbolIndex = _aioBuildKrThemeSymbolIndex();
    (window.KR_SUB_THEMES || []).forEach(function(theme) { _aioPushThemeSymbols(out, theme); });
    var krMap = window.KR_THEME_MAP || {};
    Object.keys(krMap).forEach(function(key) {
      (krMap[key] || []).forEach(function(item) { _aioPushSymbol(out, _aioResolveKrThemeSymbol(item && (item.yahoo || item.sym || item.code), krThemeSymbolIndex)); });
    });
  }
  return _aioUniq(out).slice(0, limit);
}

function _aioCollectDomLiveSymbols(pageId) {
  var id = String(pageId || '').replace(/^page-/, '') || 'home';
  var root = null;
  var out = [];
  try { root = document.getElementById('page-' + id); } catch(_) {}
  if (!root) return out;
  var attrs = ['data-live-price', 'data-live-chg', 'data-live-pct', 'data-live-field'];
  try {
    root.querySelectorAll(attrs.map(function(a) { return '[' + a + ']'; }).join(',')).forEach(function(el) {
      attrs.forEach(function(attr) {
        var v = el.getAttribute(attr);
        if (!v || /^\$\{/.test(v)) return;
        if (attr === 'data-live-field') v = String(v).split(':')[0];
        _aioPushSymbol(out, v);
      });
    });
  } catch(_) {}
  return _aioUniq(out);
}
window._aioCollectDomLiveSymbols = _aioCollectDomLiveSymbols;

window.AIO.collectPageDataSymbols = function(pageId, scope) {
  var base = _aioResolveRequirementProfile(pageId);
  return _aioUniq((base.symbols || []).concat(_aioCollectDynamicPageSymbols(pageId, scope || {})).concat(_aioCollectDomLiveSymbols(pageId)));
};

