  try { document.dispatchEvent(new CustomEvent('aio:entityChanged', { detail: { id: tkr, source: 'ticker-selection' } })); } catch (_) {}
  // P1449 (검토판 9): the three 종목-screen search boxes must move with the selection. A previous
